/// <summary>
/// One row of HSMobileOpsPostQueue, as the Activity screen needs it - what was submitted, what
/// it is now, and why, without exposing the raw LinesJson a status list has no use for.
/// </summary>
[DataContractAttribute]
class HSMobileOpsPostQueueEntry
{
    str         sourceId;
    str         documentType;
    str         status;
    str         errorMessage;
    utcdatetime receivedUtc;
    utcdatetime processedUtc;

}

Method.Source:
[DataMemberAttribute('SourceId')]
public str parmSourceId(str _value = sourceId)
{
    sourceId = _value;
    return sourceId;
}

[DataMemberAttribute('DocumentType')]
public str parmDocumentType(str _value = documentType)
{
    documentType = _value;
    return documentType;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _value = status)
{
    status = _value;
    return status;
}

[DataMemberAttribute('ErrorMessage')]
public str parmErrorMessage(str _value = errorMessage)
{
    errorMessage = _value;
    return errorMessage;
}

[DataMemberAttribute('ReceivedUtc')]
public utcdatetime parmReceivedUtc(utcdatetime _value = receivedUtc)
{
    receivedUtc = _value;
    return receivedUtc;
}

[DataMemberAttribute('ProcessedUtc')]
public utcdatetime parmProcessedUtc(utcdatetime _value = processedUtc)
{
    processedUtc = _value;
    return processedUtc;
}
